insert into public.chapters (chapter, title, scenarios) values (2, 'The Art of Deciding: How to Master Your Choices', '{}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note) values
('c2-q01', 2, 1, null, 'A manager chooses to ignore a rigorous decision-making process and selects TV monitor A over monitor B because he "trusts" company A more than company B. If the decision he made was rational, which one of the following is true?', '["Monitor A is really the better choice.", "The manager should have included \"trust\" as a criterion.", "Monitor B is really the better choice.", "The manager must have made a mistake in calculating his weighted criteria."]'::jsonb, 'B', null, 'Not marked on the sheet. If trust drove the choice and the decision is to be rational, "trust" must be one of the explicit decision criteria (step 2 of the decision-making process).'),
('c2-q02', 2, 2, null, 'In allocating weights to the decision criteria, which one of the following is most helpful to remember?', '["All weights must be the same.", "The total of the weights must equal 100.", "The high score should be a 10, and no two criteria should be assigned the same weight.", "Assign the most important criterion a score, and then assign weights against that standard."]'::jsonb, 'D', null, 'Not marked on the sheet. Textbook: give the most important criterion a score (e.g. 10) and weight the others against that standard.'),
('c2-q03', 2, 3, null, 'Sondra has decided to purchase a new system. After obtaining permission, she has ordered the system from a reputable company. Which stage of the decision-making process is she carrying out in making the order?', '["analyzing alternative solutions", "selecting an alternative", "implementing the alternative", "identifying the problem"]'::jsonb, 'C', null, 'Not marked on the sheet. The choice was already made; ordering = putting the decision into action (implementation).'),
('c2-q04', 2, 4, null, 'Maximizing value for an organization means making sure that ________.', '["the organization makes money", "the best interests of the organization are addressed", "the decision made is as rational as possible", "the decision is as simple as possible"]'::jsonb, 'B', null, 'Not marked on the sheet. Rational decision making assumes decisions are made in the best interests of the organization.'),
('c2-q05', 2, 5, null, 'Which pair of terms is correctly matched up?', '["structured problem, programmed decision", "structured problem, structured decision", "unstructured problem, programmed decision", "structured problem, nonprogrammed decision"]'::jsonb, 'A', 'A', null),
('c2-q06', 2, 6, null, 'A key to what is commonly used to assess risk is for a decision maker to examine the ________ an investment.', '["promises made by a company for", "ads posted by a company for", "historical data for", "minor details of"]'::jsonb, 'C', 'C', null),
('c2-q07', 2, 7, null, 'Which one of the following is a primary characteristic of groupthink?', '["conflict among group members", "failure to reach consensus within a group", "complete conformity among group members", "candidness and openness within a group"]'::jsonb, 'C', 'C', null),
('c2-q08', 2, 8, null, 'Which one of the following is NOT a factor that can increase the probability of groupthink?', '["Influential group members dominate the discussion and the decision-making process.", "Group leaders stress the importance of consensus above all other concerns.", "The group has more than 40 group members.", "Group leaders solicit ideas from all group members without passing judgment on their ideas."]'::jsonb, 'D', 'D', null),
('c2-q09', 2, 9, null, 'Which one of the following group techniques is relatively simple and is used exclusively to generate creative ideas in a group setting?', '["brainstorming", "nominal group technique", "groupthink", "electronic meetings"]'::jsonb, 'A', 'A', null),
('c2-q10', 2, 10, null, 'A manager can faithfully execute the decision-making process but still end up with nothing of value if ________.', '["he fails to identify the correct problem", "he fails to assign number values to different criteria", "he solves the problem inefficiently", "he fails to correctly identify the steps of the process"]'::jsonb, 'A', null, 'Not marked on the sheet. If the wrong problem is identified, even a perfect process solves the wrong thing.'),
('c2-q11', 2, 11, null, 'A manager is considering purchasing new computers for her department. The manager spends time assessing the computers her department now has. Which stage of the decision-making process is she going through?', '["identification of a problem", "identification of decision criteria", "development of alternatives", "implementation of an alternative"]'::jsonb, 'A', null, 'Not marked on the sheet. Assessing the current situation (discrepancy between current and desired state) = identifying the problem.'),
('c2-q12', 2, 12, null, 'A manager is determining what kind of new computers she should purchase for her department. She has made a list of five different computer models for consideration. Which stage of the decision-making process is this?', '["selection of an alternative", "identification of decision criteria", "development of alternatives", "analysis of alternatives"]'::jsonb, 'C', 'C', null),
('c2-q13', 2, 13, null, 'After purchasing new computers for her department, a manager is now comparing the performance of the new computers to the computers they replaced. Which stage of the decision-making process is she carrying out?', '["analysis of alternatives", "evaluation of decision effectiveness", "selection of an alternative", "implementation of an alternative"]'::jsonb, 'B', 'B', null),
('c2-q14', 2, 14, null, 'For a high-tech bicycle buyer, decision criteria would be determined by ________.', '["whatever most bike buyers recommend", "expert ratings in bike magazines", "technical specifications", "personal preferences of the buyer"]'::jsonb, 'D', 'D', null),
('c2-q15', 2, 15, null, 'What is a heuristic?', '["a complicated and systematic method of decision making", "a purely intuitive method of decision making", "a totally unreliable method of decision making", "a shortcut or rule of thumb that is used for decision making"]'::jsonb, 'D', 'D', null),
('c2-q16', 2, 16, null, 'Because they are not systematic or comprehensive, using heuristics in place of an eight-step decision-making process can lead to ________.', '["errors and biases", "consistently better decisions", "more imaginative decisions", "decisions that more directly solve problems"]'::jsonb, 'A', 'A', null),
('c2-q17', 2, 17, null, 'A banker opts for short-term gain despite indications that his decision might not pay off in the long run. Which error or bias is the banker guilty of?', '["overconfidence", "immediate gratification", "selective perception bias", "representation"]'::jsonb, 'B', 'B', null),
('c2-q18', 2, 18, null, 'A scientist cites two studies that show a positive effect for her drug and ignores five other studies that show a negative effect. Which error or bias is she committing?', '["hindsight", "anchoring effect", "confirmation bias", "self-serving"]'::jsonb, 'C', 'C', null),
('c2-q19', 2, 19, null, 'One legislator sees decreased tax revenue as the key problem in the budget. A second legislator sees increased spending as the problem. Each of these legislators has a(n) ________.', '["representation bias", "self-serving bias", "availability bias", "framing bias"]'::jsonb, 'D', 'D', null),
('c2-q20', 2, 20, null, 'It is assumed that a rational decision maker ________.', '["would never make a wrong choice", "would be subjective and impractical", "would face only difficult decisions", "would be objective and logical"]'::jsonb, 'D', 'D', null),
('c2-q21', 2, 21, null, 'It is assumed that in most cases the decisions of all managers are limited by ________.', '["greed and short-sightedness", "having too much information", "not being able to analyze all information for all alternatives", "not being able to act rationally or in the best interests of their organization"]'::jsonb, 'C', 'C', null),
('c2-q22', 2, 22, null, 'Which term best characterizes a decision that has bounded rationality?', '["virtually perfect", "rigorous and comprehensive", "not good enough", "just good enough"]'::jsonb, 'D', null, 'Not marked on the sheet. Bounded rationality leads to satisficing = accepting solutions that are "good enough".'),
('c2-q23', 2, 23, null, 'Which one of the following is the best definition for the word satisfice?', '["very satisfying", "not sufficient", "accepts a less than perfect solution", "requires a perfect solution"]'::jsonb, 'C', null, 'Not marked on the sheet. Satisfice = accept a solution that is good enough, not perfect.'),
('c2-q24', 2, 24, null, 'Sticking to a decision despite evidence that it is a mistake is called ________.', '["escalation of commitment", "escalation of rationality", "satisficing commitment", "error enhancement"]'::jsonb, 'A', null, 'Not marked on the sheet. Textbook definition of escalation of commitment.'),
('c2-q25', 2, 25, null, 'Which model of decision making takes advantage of unconscious reasoning?', '["rational", "nonrational", "intuitive", "factual"]'::jsonb, 'C', 'B', 'CORRECTED: B (nonrational) is circled on the sheet. The textbook defines intuitive decision making as making decisions on the basis of experience, feelings and accumulated judgment – "subconscious mental processing" is one of its explicit facets. Please double-check with your instructor.'),
('c2-q26', 2, 26, null, 'Structured problems are ________.', '["ambiguous", "clear and straightforward", "undefined and vague", "incomplete"]'::jsonb, 'C', 'C', 'On the sheet both A and C are circled. Structured problems are straightforward, familiar and easily defined → C.'),
('c2-q27', 2, 27, null, 'Unstructured problems are ________.', '["perfectly rational", "clear and straightforward", "situations in which all options are known", "situations in which all options are not known"]'::jsonb, 'D', null, 'Not marked on the sheet. Unstructured problems are new/unusual, with ambiguous or incomplete information.'),
('c2-q28', 2, 28, null, 'Which one of the following is an example of a structured problem?', '["designing a new digital music player", "hiring a lawyer", "deciding shipping options for a vacuum cleaner", "drafting a quarterback for a pro football team"]'::jsonb, 'C', null, 'Not marked on the sheet. Shipping options are a routine, recurring, well-defined decision; the others are new or unusual.'),
('c2-q29', 2, 29, null, 'Programmed decisions work well for solving ________.', '["structured problems", "unstructured problems", "both structured and unstructured problems", "poorly defined problems"]'::jsonb, 'A', 'B', 'CORRECTED: B is circled on the sheet. Programmed decisions are repetitive decisions handled by a routine approach – they are used for STRUCTURED problems (see also question 5: structured problem ↔ programmed decision).'),
('c2-q30', 2, 30, null, 'Top managers in an organization tend to ________.', '["make programmed decisions", "solve structured problems", "make nonprogrammed decisions", "solve well-defined problems"]'::jsonb, 'C', 'C', null),
('c2-q31', 2, 31, null, 'Which three conditions do decision makers face?', '["certainty, risk, uncertainty", "certainty, uncertainty, confidence", "risk, high risk, low risk", "certainty, risk, high risk"]'::jsonb, 'A', null, 'Not marked on the sheet. Textbook: certainty, risk and uncertainty.'),
('c2-q32', 2, 32, null, '________ is a situation in which a decision maker has incomplete information about outcomes and does not have the ability to reasonably estimate outcomes that are not known.', '["Certainty", "Risk", "Uncertainty", "High certainty"]'::jsonb, 'C', null, 'Not marked on the sheet. Under risk, probabilities can be estimated; under uncertainty they cannot.'),
('c2-q33', 2, 33, null, 'One advantage of group decision making is that it usually provides ________ than individual decision making.', '["faster decisions", "more ethical decisions", "less confusion", "more information"]'::jsonb, 'D', 'D', null),
('c2-q34', 2, 34, null, 'Group decisions generally feature ________ acceptance than decisions made by an individual.', '["greater", "less", "neither greater nor less", "more enthusiastic"]'::jsonb, 'A', 'A', null),
('c2-q35', 2, 35, null, 'Since all members of a group are rarely equal in status, most groups suffer from ________.', '["minority domination", "majority domination", "too much diversity", "gridlock"]'::jsonb, 'A', null, 'Not marked on the sheet. Textbook drawback of groups: minority domination – a few members dominate due to unequal status.'),
('c2-q36', 2, 36, null, 'Mid-level managers in a country with high power distance are ________ than managers from a low power distance country.', '["more likely to make risky decisions", "less likely to make risky decisions", "less likely to make safe, conservative decisions", "more likely to disagree with their leaders'' decisions"]'::jsonb, 'B', null, 'Not marked on the sheet. In high power distance cultures, important decisions are left to the top; mid-level managers defer and avoid risk.'),
('c2-q37', 2, 37, null, 'Mid-level managers in a country with low uncertainty avoidance are ________ than managers from a high uncertainty avoidance country.', '["more likely to make risky decisions", "less likely to make risky decisions", "less likely to make foolish decisions", "more likely to avoid making decisions"]'::jsonb, 'A', null, 'Not marked on the sheet. Low uncertainty avoidance = comfortable with ambiguity and risk.'),
('c2-q38', 2, 38, null, 'The use of ringisei in Japanese organizations reflects which one of the following values in Japanese culture?', '["tradition-following", "consensus-seeking", "risk taking", "go-it-alone"]'::jsonb, 'B', 'A', 'CORRECTED: A is circled on the sheet. Ringisei are consensus-forming group decisions – the textbook links them to the Japanese value of conformity and cooperation, i.e. consensus-seeking. Please double-check with your instructor.'),
('c2-q39', 2, 39, null, 'When dealing with international organizations, managers must be ________ in order to accommodate the managing styles of different cultures.', '["as flexible as possible", "as inflexible as possible", "as strict as possible", "as thorough as possible"]'::jsonb, 'A', null, 'Not marked on the sheet.'),
('c2-q40', 2, 40, null, 'Which one of the following tends to impede a person''s creativity?', '["providing time and resources", "clearly defined goals", "being watched while you work", "internal motivation"]'::jsonb, 'C', 'C', null)
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c2-o1', 2, 1, 'In a short essay, discuss why creativity is important to decision making. Describe a situation in which a creative solution is used to solve a problem.', 'Creativity – the ability to combine ideas in a unique way or to make unusual associations – is important because it lets a decision maker appraise and understand a problem more fully, "see" problems others can''t, and, most importantly, identify all viable alternatives (step 4 of the decision process). Without creativity, managers tend to pick from obvious, conventional options and may miss the best solution, especially for unstructured problems.
